    "path": "portfolio-o-guard-que-nunca-chegou-a-rodar.mdx",
    "slug": "portfolio-o-guard-que-nunca-chegou-a-rodar",
    "lang": "pt",
    "title": "O guard que nunca chegou a rodar",
